import React from "react";
import { IconButton, Button } from "../../index";
import { SvgMpaIcon } from "../../assets/icons/index";
import "./HorizontalButtonCard.scss";

export interface HorizontalButtonCardProps {
  id?: string;
  cardType?: "elevated" | "filled" | "outline";
  types?: "Card01" | "Card02";
  showImage?: boolean;
  imageUrl?: string;
  title?: string;
  subText?: string;
  description?: string;
  showDivider?: boolean;  
  showCTA?: boolean;
  showSuplementalIconButton?: boolean; 
  headerButtonIcon?: keyof typeof SvgMpaIcon | string;
  primaryIcon?: keyof typeof SvgMpaIcon | string;
  secondaryIcon?: keyof typeof SvgMpaIcon | string;  
  onPrimaryActionText?: string;
  onPrimaryActionClick?: () => void;  
  onPrimarIconButtonClick?: () => void;
  onSecondaryIconButtonClick?: () => void;
  onHeaderIconButtonClick?: () => void;  
  disabled?: boolean;
}

const HorizontalButtonCard: React.FC<HorizontalButtonCardProps> = ({
  id,
  cardType = "elevated",
  types = "Card01",
  showImage = true,
  imageUrl,
  title,
  subText,
  description,  
  headerButtonIcon,
  primaryIcon,
  secondaryIcon,
  onPrimaryActionText = "Action",
  onPrimaryActionClick,  
  onPrimarIconButtonClick,
  onSecondaryIconButtonClick,
  onHeaderIconButtonClick,
  showDivider = true,
  showCTA = true,
  showSuplementalIconButton = true,
  disabled = false,
}) => {
  const showimageFullWidth = types === "Card01";

  return (
    <div className= {`mpa-cardwrapper ${disabled ? "disabled" : ""}`}>
      <div
        className={`mpa-hbcardLayoutWrapper ${cardType} ${
          !showImage ? "no-image" : ""
        }`}
      >
        {showImage && (
          <div
            className={`mpa-hbcardImageContainer ${
              showimageFullWidth ? "full-width" : "with-padding"
            }`}
          >
            <img
              src={imageUrl}
              alt={(id ?? "") + " Description of image"}
              className="mpa-hbcardImage"
            />
          </div>
        )}

        <div className="mpa-hbcardRightContent">
          <div
            className={`mpa-hbcardSupportContainer ${
              types === "Card02" ? "Card02" : ""
            }`}
          >
            <div className="mpa-hbcardSupportTextContent">
              <div className="horizontalHeader">
                <div className="mpa-hbcardSupportTextLeft">
                  <div className="mpa-hbcardSupportTitle" title={title}>
                    {title}
                  </div>
                  <div className="mpa-hbcardSupportsubTitle" title={subText}>
                    {subText}
                  </div>
                </div>
                <div className="mpa-hbcardSupportIconRight">
                  <IconButton
                    id={"id"}
                    icon={headerButtonIcon}
                    btnType="standard"
                    size="medium"
                    onClick={onHeaderIconButtonClick}
                  />
                </div>
              </div>

              <div
                className="mpa-hbcardSupportsubTitle mpa-hbcarddescription"
                title={description}
              >
                {description}
              </div>
            </div>
            {showCTA && 
              <div className="mpa-hbcardSupportActionContainer">
                {showDivider && (
                  <div className="mpa-hbcardSupportActionDivider" />
                )}
                <div className="mpa-hbcardSupportActionButtonContainer">
                  <Button
                    id="id"
                    btnType="filled"
                    onClick={onPrimaryActionClick}
                    className="mpa-leftActionBtn"
                    label={onPrimaryActionText}
                  >   
                  </Button>

                  {showSuplementalIconButton &&
                    <div className="mpa-hbcardSuplementalAction">
                      <IconButton
                        id="id"
                        icon={primaryIcon}
                        btnType="outline"
                        shape="circle"
                        size="medium"
                        onClick={onPrimarIconButtonClick}
                      />
                      <IconButton
                        id="id"
                        icon={secondaryIcon}
                        btnType="outline"
                        shape="circle"
                        size="medium"
                        onClick={onSecondaryIconButtonClick}
                      />
                    </div>
                    }       
                </div>
              </div>
            }   
          </div>
        </div>
      </div>
    </div>
  );
};

export default HorizontalButtonCard;
